const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const brooklyn = ee.Geometry.Polygon([
    [-74.042, 40.570], [-73.855, 40.570],
    [-73.855, 40.739], [-74.042, 40.739],
    [-74.042, 40.570]
  ]);

  // 2. Data Acquisition & Check
  function getNO2Data(year) {
    const startDate = year + '-10-01';
    const endDate = year + '-10-23';

    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(brooklyn)
      .select('tropospheric_NO2_column_number_density');

    return collection;
  }

  const collections = {
    '2018': getNO2Data('2018'),
    '2019': getNO2Data('2019'), 
    '2021': getNO2Data('2021')
  };

  // Check for empty collections
  for (const [year, col] of Object.entries(collections)) {
    const size = col.size().getInfo();
    print(year + ' Images: ' + size);
    if (size === 0) {
      print('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Calculate mean NO2 for each period
  const results = {};

  for (const [year, col] of Object.entries(collections)) {
    const meanImage = col.mean();

    // Get pixel count and mean value
    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: brooklyn,
      scale: 1000,
      maxPixels: 1e9
    });

    const meanVal = stats.get('tropospheric_NO2_column_number_density_mean').getInfo();
    const count = stats.get('tropospheric_NO2_column_number_density_count').getInfo();

    print(year + ' Mean NO2: ' + (meanVal ? meanVal.toFixed(6) : 'null') + ', Pixels: ' + count);

    // Check for no valid pixels
    if (count === 0) {
      print('<answer>C2</answer>');
      return;
    }

    // Check for calculation failure
    if (meanVal === null || meanVal === undefined || !isFinite(meanVal)) {
      print('<answer>C3</answer>');
      return;
    }

    results[year] = meanVal;
  }

  // 4. Comparison logic
  const no2_2021 = results['2021'];
  const no2_2019 = results['2019'];
  const no2_2018 = results['2018'];

  print('Comparison: 2021 (' + no2_2021.toFixed(6) + ') vs 2019 (' + no2_2019.toFixed(6) + 
        ') vs 2018 (' + no2_2018.toFixed(6) + ')');

  // Check if 2021 is lower than both 2019 AND 2018
  if (no2_2021 < no2_2019 && no2_2021 < no2_2018) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
